import { helper, scale } from './b';

export function total(values: number[]): number {
  let sum = 0;
  for (const value of values) {
    sum += value;
  }
  return scale(sum);
}

/** Adds one to `x`. */
export function helper(x: number): number {
  return x + 1;
}

export function scale(x: number): number {
  return x * 2;
}

import { helper, scale } from './b';

export function total(values: number[]): number {
  let sum = 0;
  for (const value of values) {
    sum += helper(value);
  }
  return scale(sum);
}

export const answer = total([1, 2, 3]);
